//! Flood scenarios. Two kinds: real child processes printing through real PTYs into the
//! engine, and generated bytes fed to the engine from memory ("parse only").

use std::io::{Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

use portable_pty::{native_pty_system, CommandBuilder, PtySize};
use rwk_core::project::ProjectRoot;
use rwk_core::sessions::{SessionId, SessionKind, SessionLaunch, TerminalHost, TerminalSize};
use rwk_core::terminal::{EngineOptions, ProgramPaths, PtyTerminalHost, TerminalEngine};

use crate::stats::{summarize, LatencySummary};

/// What the flooding child prints.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FloodKind {
    /// `seq 1 N`: short plain lines.
    Plain,
    /// Agent-like output: SGR colours and long lines.
    Color,
}

/// What one flood measured.
#[derive(Debug, Clone, Copy)]
pub struct FloodResult {
    /// Start until every session was fully parsed.
    pub elapsed: Duration,
    /// Bytes the parsers applied, all sessions together.
    pub bytes: u64,
    /// Snapshot latency over all sessions; empty when no sampler ran.
    pub latency: LatencySummary,
    /// Wake-ups the engines requested.
    pub wakes: u64,
}

const COLOR_LINE: &str = "\x1b[32mINFO\x1b[0m \x1b[1;34mrun\x1b[0m step=12345 \x1b[33mwarn\x1b[0m path=/home/alaz/dev/core/R-AI-OS/crates/x.rs:42 ok";
const TERMINAL: TerminalSize = TerminalSize {
    cols: 100,
    rows: 30,
};
const DEADLINE: Duration = Duration::from_secs(180);

fn flood_script(kind: FloodKind, lines: u64) -> String {
    let body = match kind {
        FloodKind::Plain => format!("seq 1 {lines}"),
        FloodKind::Color => {
            let escaped = COLOR_LINE.replace('\x1b', "\\033");
            format!("yes \"$(printf '{escaped}')\" | head -n {lines}")
        }
    };
    format!("#!/bin/bash\n{body}\n")
}

fn write_script(path: &Path, text: &str) -> std::io::Result<()> {
    std::fs::write(path, text)?;
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755))
}

/// The bytes a flood of `lines` lines consists of, as the terminal would receive them.
pub fn payload(kind: FloodKind, lines: u64) -> Vec<u8> {
    match kind {
        FloodKind::Plain => {
            let mut out = Vec::with_capacity(lines as usize * 8);
            for n in 1..=lines {
                let _ = write!(out, "{n}\r\n");
            }
            out
        }
        FloodKind::Color => format!("{COLOR_LINE}\r\n")
            .repeat(lines as usize)
            .into_bytes(),
    }
}

/// Takes timed snapshots of every engine at a fixed interval, like a UI redrawing.
fn start_samplers(
    engines: &[Arc<TerminalEngine>],
    interval: Option<Duration>,
    stop: &Arc<AtomicBool>,
) -> Vec<thread::JoinHandle<Vec<u64>>> {
    let Some(interval) = interval else {
        return Vec::new();
    };
    engines
        .iter()
        .map(|engine| {
            let engine = engine.clone();
            let stop = stop.clone();
            thread::spawn(move || {
                let mut samples = Vec::with_capacity(4096);
                while !stop.load(Ordering::Relaxed) {
                    let begun = Instant::now();
                    let snapshot = engine.snapshot();
                    samples.push(begun.elapsed().as_micros() as u64);
                    std::hint::black_box(&snapshot);
                    thread::sleep(interval);
                }
                samples
            })
        })
        .collect()
}

fn collect(samplers: Vec<thread::JoinHandle<Vec<u64>>>) -> LatencySummary {
    summarize(
        samplers
            .into_iter()
            .flat_map(|sampler| sampler.join().unwrap_or_default())
            .collect(),
    )
}

/// Runs `sessions` identical floods through real PTYs at once. With `sample_every`, a UI-like
/// sampler times a snapshot of every session at that interval.
pub fn run_pty_flood(
    kind: FloodKind,
    lines: u64,
    sessions: usize,
    sample_every: Option<Duration>,
) -> Result<FloodResult, String> {
    let dir = tempfile::tempdir().map_err(|error| error.to_string())?;
    let script = dir.path().join("flood.sh");
    write_script(&script, &flood_script(kind, lines)).map_err(|error| error.to_string())?;
    let project = ProjectRoot::open(dir.path().to_path_buf()).map_err(|e| format!("{e:?}"))?;
    let wakes = Arc::new(AtomicU64::new(0));
    let counter = wakes.clone();
    let host = PtyTerminalHost::new(
        ProgramPaths {
            shell: Some(script),
            raios: None,
        },
        Arc::new(move |_: &SessionId| {
            counter.fetch_add(1, Ordering::Relaxed);
        }),
    );

    let started = Instant::now();
    let mut ids = Vec::new();
    for _ in 0..sessions {
        ids.push(spawn_retrying(&host, &project)?);
    }
    let engines: Vec<_> = ids
        .iter()
        .map(|id| host.engine(id).ok_or("session vanished"))
        .collect::<Result<_, _>>()?;
    let stop = Arc::new(AtomicBool::new(false));
    let samplers = start_samplers(&engines, sample_every, &stop);
    for engine in &engines {
        if !engine.wait_output_closed(DEADLINE.saturating_sub(started.elapsed())) {
            return Err("a flood did not finish within 180 s".into());
        }
    }
    let elapsed = started.elapsed();
    stop.store(true, Ordering::Relaxed);
    let latency = collect(samplers);
    let bytes = engines.iter().map(|e| e.stats().bytes_parsed).sum();
    for id in &ids {
        host.remove(id);
    }
    Ok(FloodResult {
        elapsed,
        bytes,
        latency,
        wakes: wakes.load(Ordering::Relaxed),
    })
}

/// Feeds a prepared payload to one engine through a pipe: the parse speed with no PTY and no
/// producer process. Generating the payload is not part of the time.
pub fn run_parse_only(payload: &[u8]) -> Result<FloodResult, String> {
    let (reader, mut writer) = std::io::pipe().map_err(|error| error.to_string())?;
    let wakes = Arc::new(AtomicU64::new(0));
    let counter = wakes.clone();
    let engine = Arc::new(
        TerminalEngine::start(
            Box::new(reader),
            Box::new(std::io::sink()),
            EngineOptions {
                size: TERMINAL,
                ..EngineOptions::default()
            },
            Arc::new(move || {
                counter.fetch_add(1, Ordering::Relaxed);
            }),
        )
        .map_err(|e| format!("{e:?}"))?,
    );
    let started = Instant::now();
    let data = payload.to_vec();
    let producer = thread::spawn(move || writer.write_all(&data));
    if !engine.wait_output_closed(DEADLINE) {
        return Err("the parse did not finish within 180 s".into());
    }
    let elapsed = started.elapsed();
    producer
        .join()
        .map_err(|_| "the producer panicked")?
        .map_err(|error| error.to_string())?;
    Ok(FloodResult {
        elapsed,
        bytes: engine.stats().bytes_parsed,
        latency: LatencySummary::default(),
        wakes: wakes.load(Ordering::Relaxed),
    })
}

/// How long the same flood takes through a real PTY when the reader only discards the bytes.
/// This is the part of the time that belongs to the kernel and the producer, not to the engine.
pub fn pty_floor(kind: FloodKind, lines: u64) -> Result<Duration, String> {
    let dir = tempfile::tempdir().map_err(|error| error.to_string())?;
    let script: PathBuf = dir.path().join("flood.sh");
    write_script(&script, &flood_script(kind, lines)).map_err(|error| error.to_string())?;
    let pair = native_pty_system()
        .openpty(PtySize {
            rows: TERMINAL.rows,
            cols: TERMINAL.cols,
            pixel_width: 0,
            pixel_height: 0,
        })
        .map_err(|error| error.to_string())?;
    let mut reader = pair.master.try_clone_reader().map_err(|e| e.to_string())?;
    let started = Instant::now();
    let mut child = spawn_floor_child(&pair, &script, dir.path())?;
    drop(pair.slave);
    let mut buffer = vec![0u8; 64 * 1024];
    while let Ok(count) = reader.read(&mut buffer) {
        if count == 0 {
            break;
        }
    }
    let elapsed = started.elapsed();
    let _ = child.wait();
    Ok(elapsed)
}

fn spawn_floor_child(
    pair: &portable_pty::PtyPair,
    script: &Path,
    cwd: &Path,
) -> Result<Box<dyn portable_pty::Child + Send + Sync>, String> {
    for _ in 0..20 {
        let mut command = CommandBuilder::new(script);
        command.cwd(cwd);
        match pair.slave.spawn_command(command) {
            Ok(child) => return Ok(child),
            Err(error) if error.to_string().contains("Text file busy") => {
                thread::sleep(Duration::from_millis(25));
            }
            Err(error) => return Err(error.to_string()),
        }
    }
    Err("the flood script stayed busy".into())
}

/// Spawns, retrying when the kernel reports the freshly written script as busy.
fn spawn_retrying(host: &PtyTerminalHost, project: &ProjectRoot) -> Result<SessionId, String> {
    let launch = SessionLaunch::default();
    for _ in 0..20 {
        match host.spawn(project, SessionKind::Shell, &launch, TERMINAL) {
            Ok(id) => return Ok(id),
            Err(error) if error.message.contains("Text file busy") => {
                thread::sleep(Duration::from_millis(25));
            }
            Err(error) => return Err(format!("{error:?}")),
        }
    }
    Err("the flood script stayed busy".into())
}

/// Peak resident set size of this process in MiB, from `VmHWM`.
pub fn peak_rss_mib() -> f64 {
    std::fs::read_to_string("/proc/self/status")
        .ok()
        .and_then(|status| {
            status
                .lines()
                .find_map(|line| line.strip_prefix("VmHWM:"))
                .and_then(|rest| rest.split_whitespace().next()?.parse::<f64>().ok())
        })
        .map_or(0.0, |kib| kib / 1024.0)
}

/// Hardware threads available to this process.
pub fn thread_count() -> usize {
    thread::available_parallelism().map_or(1, |n| n.get())
}

/// One line describing the CPU, so a report can be judged against its hardware.
pub fn cpu_model() -> String {
    std::fs::read_to_string("/proc/cpuinfo")
        .ok()
        .and_then(|info| {
            info.lines()
                .find_map(|line| line.strip_prefix("model name"))
                .map(|rest| rest.trim_start_matches([' ', '\t', ':']).trim().to_owned())
        })
        .unwrap_or_else(|| "unknown cpu".into())
}
